use risk_engine::{EventKind,TransitionForecast};use serde::{Deserialize,Serialize};use std::{collections::{BTreeMap,BTreeSet},fs::{self,File,OpenOptions},io::{BufRead,BufReader,Write},path::{Path,PathBuf}};use thiserror::Error;use uuid::Uuid;
#[derive(Clone,Debug,PartialEq,Serialize,Deserialize)]pub struct Outcome{pub outcome_id:Uuid,pub forecast_id:Uuid,pub event:EventKind,pub horizon_seconds:u64,pub window_start_ns:i64,pub window_end_ns:i64,pub as_known_at_ns:i64,pub occurred:bool,pub first_passage_ns:Option<i64>,pub maximum_excursion:f64,pub label_definition_id:String,pub source_range_hash:String}
#[derive(Clone,Debug,PartialEq,Serialize,Deserialize)]#[serde(tag="kind",content="value",rename_all="snake_case")]pub enum ShadowPayload{Forecast(TransitionForecast),Outcome(Outcome)}
#[derive(Clone,Debug,PartialEq,Serialize,Deserialize)]pub struct ShadowEntry{pub sequence:u64,pub appended_at_ns:i64,pub previous_hash:String,pub entry_hash:String,pub payload:ShadowPayload}
#[derive(Clone,Debug,PartialEq,Serialize,Deserialize)]pub struct JoinedOutcome{pub forecast_id:Uuid,pub asset:String,pub event:EventKind,pub horizon_seconds:u64,pub probability:f64,pub occurred:bool,pub issued_at_ns:i64,pub outcome_as_known_at_ns:i64,pub model_package_id:String}
pub struct ShadowLedger{path:PathBuf,sequence:u64,head:[u8;32],forecast_ids:BTreeSet<Uuid>,outcome_keys:BTreeSet<(Uuid,u64)>}
impl ShadowLedger{pub fn open(path:impl Into<PathBuf>)->Result<Self,ShadowError>{let path=path.into();if let Some(parent)=path.parent(){fs::create_dir_all(parent)?;if fs::symlink_metadata(parent)?.file_type().is_symlink(){return Err(ShadowError::Unsafe)}}if !path.exists(){let mut o=OpenOptions::new();o.create_new(true).write(true);#[cfg(unix)]{use std::os::unix::fs::OpenOptionsExt;o.mode(0o600);}o.open(&path)?.sync_all()?}let(seq,head,ids,keys)=verify_file(&path)?;Ok(Self{path,sequence:seq,head,forecast_ids:ids,outcome_keys:keys})}pub fn append_forecast(&mut self,f:TransitionForecast,at:i64)->Result<(),ShadowError>{f.validate().map_err(|_|ShadowError::Forecast)?;if !self.forecast_ids.insert(f.forecast_id){return Err(ShadowError::Duplicate)}self.append(ShadowPayload::Forecast(f),at)}pub fn append_outcome(&mut self,o:Outcome,at:i64)->Result<(),ShadowError>{if !self.forecast_ids.contains(&o.forecast_id)||o.horizon_seconds==0||o.as_known_at_ns<o.window_end_ns||o.window_start_ns>=o.window_end_ns||!self.outcome_keys.insert((o.forecast_id,o.horizon_seconds)){return Err(ShadowError::Outcome)}self.append(ShadowPayload::Outcome(o),at)}fn append(&mut self,payload:ShadowPayload,at:i64)->Result<(),ShadowError>{let sequence=self.sequence.checked_add(1).ok_or(ShadowError::Overflow)?;let bytes=serde_json::to_vec(&payload)?;let hash=hash(self.head,sequence,at,&bytes);let entry=ShadowEntry{sequence,appended_at_ns:at,previous_hash:hex::encode(self.head),entry_hash:hex::encode(hash),payload};let mut f=OpenOptions::new().append(true).open(&self.path)?;f.write_all(&serde_json::to_vec(&entry)?)?;f.write_all(b"\n")?;f.sync_data()?;self.sequence=sequence;self.head=hash;Ok(())}pub fn joined(&self)->Result<Vec<JoinedOutcome>,ShadowError>{let mut forecasts=BTreeMap::new();let mut result=Vec::new();for line in BufReader::new(File::open(&self.path)?).lines(){let e:ShadowEntry=serde_json::from_str(&line?)?;match e.payload{ShadowPayload::Forecast(f)=>{forecasts.insert(f.forecast_id,f);},ShadowPayload::Outcome(o)=>{let f=forecasts.get(&o.forecast_id).ok_or(ShadowError::Ordering)?;if o.as_known_at_ns<=f.issued_at_ns{return Err(ShadowError::Ordering)}let p=f.points.iter().find(|p|p.horizon_seconds==o.horizon_seconds).ok_or(ShadowError::Outcome)?;result.push(JoinedOutcome{forecast_id:f.forecast_id,asset:f.asset.clone(),event:f.event,horizon_seconds:o.horizon_seconds,probability:p.cumulative_incidence,occurred:o.occurred,issued_at_ns:f.issued_at_ns,outcome_as_known_at_ns:o.as_known_at_ns,model_package_id:f.lineage.model_package_id.clone()})}}}Ok(result)}}
fn verify_file(path:&Path)->Result<(u64,[u8;32],BTreeSet<Uuid>,BTreeSet<(Uuid,u64)>),ShadowError>{let mut seq=0;let mut head=[0;32];let mut ids=BTreeSet::new();let mut keys=BTreeSet::new();for line in BufReader::new(File::open(path)?).lines(){let e:ShadowEntry=serde_json::from_str(&line?)?;if e.sequence!=seq+1||e.previous_hash!=hex::encode(head){return Err(ShadowError::Integrity)}let b=serde_json::to_vec(&e.payload)?;let h=hash(head,e.sequence,e.appended_at_ns,&b);if e.entry_hash!=hex::encode(h){return Err(ShadowError::Integrity)}match &e.payload{ShadowPayload::Forecast(f)=>{if !ids.insert(f.forecast_id){return Err(ShadowError::Duplicate)}},ShadowPayload::Outcome(o)=>{if !ids.contains(&o.forecast_id)||!keys.insert((o.forecast_id,o.horizon_seconds)){return Err(ShadowError::Ordering)}}}seq=e.sequence;head=h}Ok((seq,head,ids,keys))}
fn hash(previous:[u8;32],sequence:u64,at:i64,payload:&[u8])->[u8;32]{let mut b=Vec::from(b"cmti:shadow-ledger:v1\0".as_slice());b.extend_from_slice(&previous);b.extend_from_slice(&sequence.to_be_bytes());b.extend_from_slice(&at.to_be_bytes());b.extend_from_slice(&(payload.len()as u64).to_be_bytes());b.extend_from_slice(payload);*blake3::hash(&b).as_bytes()}
#[derive(Debug,Error)]pub enum ShadowError{#[error("unsafe path")]Unsafe,#[error("duplicate")]Duplicate,#[error("invalid outcome")]Outcome,#[error("ordering")]Ordering,#[error("integrity")]Integrity,#[error("overflow")]Overflow,#[error("invalid forecast")]Forecast,#[error(transparent)]Io(#[from]std::io::Error),#[error(transparent)]Json(#[from]serde_json::Error)}
